# Convex hull using Brute force for small n
def convex_hull(points):
    points = sorted(points)
    if len(points) <= 1:
        return points

    # Monotone Chain algorithm
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]

hull = convex_hull(nonzero_positions)
print(f"Convex hull: {hull}")

# Check if 0->4 are inside convex hull
def point_in_convex_hull(point, hull):
    # Check if point is inside triangle formed by each hull face
    n = len(hull)
    if n < 3:
        return True
    for i in range(n):
        p0 = hull[i]
        p1 = hull[(i+1) % n]
        cross = (p1[0] - p0[0]) * (point[1] - p0[1]) - (p1[1] - p0[1]) * (point[0] - p0[0])
        if cross < 0:
            return False
    return True

