# Compute shortest path distance from each 0 to any seed (through 0s)
def shortest_path_distance(grid, start, is_zero):
    # BFS from starting cell
    from collections import deque
    n, m = len(grid), len(grid[0])
    dist = {start: 0}
    queue = deque([start])
    while queue:
        r, c = queue.popleft()
        for dr in [-1,0,1]:
            for dc in [-1,0,1]:
                if dr==0 and dc==0: continue
                nr, nc = r+dr, c+dc
                if 0 <= nr < n and 0 <= nc < m and is_zero(nr,c) and (nr,nc) not in dist:
                    dist[(nr,nc)] = dist[(r,c)] + 1
                    queue.append((nr,nc))
    return dist

